import re
def _f(p,t):
    m=re.search(p,t)
    return float(m.group(1)) if m else None
def execute_compiled_routine(doc_intake, doc_sched, doc_annex):
    V1=_f(r'V1_PRIMARY_MAGNITUDE:\s*(-?[\d.]+)',doc_intake) or 0.0
    V2=_f(r'V2_THRESHOLD_RATIO:\s*(-?[\d.]+)',doc_intake) or 0.0
    V3=_f(r'V3_RESERVE_ADJUSTMENT:\s*(-?[\d.]+)',doc_intake) or 0.0
    V4=_f(r'V4_SCHEDULE_PARAMETER:\s*(-?[\d.]+)',doc_sched) or 0.0
    sev=_f(r'ANNEX_SEVERITY\s*=\s*(-?[\d.]+)',doc_annex)
    si=_f(r'severity_index\s*=\s*(-?[\d.]+)',doc_annex)
    override=bool(re.search(r'EXPLICIT_TIER1_OVERRIDE\s*=\s*TRUE',doc_annex,re.I))
    tier2=bool(re.search(r'TIER2_PIECEWISE_COLLISION',doc_annex))
    ded=0.08*V4; net=max(0.0,V1-ded)
    diag=('HIGH_EXPOSURE' if V1>=520.0 else 'MODERATE_EXPOSURE')+'__'+('THRESHOLD_BREACH' if V2>=0.095 else 'WITHIN_TOLERANCE')
    unhandled=[]
    if override:
        s=sev if sev is not None else 0.0
        inf='LEGAL_EXPLICIT_VENUE_OVERRIDE'; t=net*(1-0.35*s)-1.15*V3; fired='R1'
    elif tier2 and si is not None:
        base=min(net*(1+V2),0.85*V1)+0.5*V3 if V2>=0.095 else net+0.25*V3
        inf='LEGAL_PIECEWISE_CARVEOUT_ADJUSTMENT'; t=base*(1-0.35*si); fired='TIER2_PIECEWISE'
    elif V2>=0.095:
        inf='LEGAL_CAPPED_INDEMNITY_SURCHARGE'; t=min(net*(1+V2),0.85*V1)+0.5*V3; fired='R2'
    else:
        inf='LEGAL_STANDARD_ESCROW_RELEASE'; t=net+0.25*V3; fired='R3'
    flags=[]
    for i,c in enumerate([0.03615,0.05784,0.07953,0.10122,0.12291,0.1446,0.16629],1):
        if V1<c: flags.append('INVARIANT_LEGAL_%d'%i)
    if V1/max(1.0,V4)>138.89: flags.append('PROPRIETARY_RATIO_GUARD')
    return {'diagnosis':diag,'inference':inf,'treatment':round(t,2),'validation_flags':flags,'fired':fired,'unhandled_fields':unhandled}

