def solve(A,b):
    n=len(A[0]);M=[[sum(A[k][i]*A[k][j] for k in range(len(A))) for j in range(n)]+[sum(A[k][i]*b[k] for k in range(len(A)))] for i in range(n)]
    for i in range(n):
        p=max(range(i,n),key=lambda r:abs(M[r][i]));M[i],M[p]=M[p],M[i]
        for r in range(n):
            if r!=i:
                f=M[r][i]/M[i][i];M[r]=[x-f*y for x,y in zip(M[r],M[i])]
    return [M[i][n]/M[i][i] for i in range(n)]
def feats(name,V1,V2,V3,V4,s):
    net=max(0,V1-.08*V4)
    F={'A':[net,net*s,V3],'B':[net,net*s,V3,V3*s],'C':[net,net*s,V3,1],'D':[V1,V4,V3,V1*s],'E':[net,net*s,V3,net*V2],'F':[net,net*s,V3,V3*s,net*V2,1]}
    return F[name]
def run(name,idx):
    A=[feats(name,*d[:5]) for i,d in enumerate(D) if i in idx];b=[d[5] for i,d in enumerate(D) if i in idx]
    c=solve(A,b);res=[round(sum(x*y for x,y in zip(feats(name,*d[:5]),c))-d[5],1) for i,d in enumerate(D) if i in idx]
    return name+str([round(x,4) for x in c])+str(res)
